#!/usr/bin/env python3
"""Build a searchable, offline inventory from the read-only commerce crawl."""
import collections, hashlib, html, json, re, sys
from pathlib import Path
before=json.loads(Path(sys.argv[1]).read_text())
after=json.loads(Path(sys.argv[2]).read_text()) if len(sys.argv)>2 else None
out=Path('reports/article-api-audit-2026-10-12');out.mkdir(exist_ok=True)
after_rows={r['route']:r for r in after['rows']} if after else {}
rows=[]
for r in before['rows']:
 if not r['article']:continue
 paragraphs=[b['text'] for b in r['blocks'] if b['tag']=='p' and not re.search(r'Affiliate|commission|BestPickZone earns|As an Amazon|Publicado|Published|Updated|By BestPickZone',b['text'],re.I)]
 fit=next((t for t in paragraphs if re.search(r'choose|start with|best for|pick|recommend|ideal|mejor|elige|recomend|para ',t,re.I)),paragraphs[0] if paragraphs else '')
 caveat=next((t for t in paragraphs if re.search(r'skip|avoid|trade.off|caveat|not for|no es|evita|however|cons:|limitation',t,re.I)),'')
 a=after_rows.get(r['route']); before_links=r['amazonLinks']; after_links=a['amazonLinks'] if a else []
 fingerprint=lambda links:hashlib.sha256(json.dumps(sorted(l['href'] for l in links),ensure_ascii=False).encode()).hexdigest()
 changed=bool(a and [l['text'] for l in before_links]!=[l['text'] for l in after_links])
 status='API data displayed' if r['apiCards'].get('creators-api') else 'API wired; fallback displayed' if r['apiTemplate'] else 'No Creators API integration'
 notes=[]
 if r['wordCount']<650:notes.append('Short article: prioritize deeper, sourced reader guidance; word count alone is not a quality verdict.')
 if not caveat:notes.append('No explicit skip/avoid wording detected; inspect tradeoffs in context.')
 if not before_links:notes.append('No Amazon links in article body; check other retailers or informational intent before adding any.')
 if r['apiTemplate']=='OrganicPilotProductCard':notes.append('Existing exact-ASIN/hostname correction is in open PR #6; not merged or rewritten here.')
 if r['route']=='/books/best-urban-fantasy-series-completed':notes.append('Prepared correction: October Daye and The Hollows are ongoing; distinguish the completed Kate Daniels main arc.')
 rows.append({'route':r['route'],'url':r['url'],'title':r['title'],'source':r['source'],'apiStatus':status,'apiTemplate':r['apiTemplate'],'liveCards':r['apiCards'],'wordsBefore':r['wordCount'],'amazonLinks':len(before_links),'tags':dict(collections.Counter(l['tag'] for l in before_links)),'destinations':dict(collections.Counter(l['destination'] for l in before_links)),'readerBenefitEvidence':fit[:650],'tradeoffEvidence':caveat[:450],'ctaLabelsBefore':list(dict.fromkeys(l['text'] for l in before_links if l['text'])),'ctaCopyChanged':changed,'bodyChanged':bool(a and r['text']!=a['text']),'beforeHrefHash':fingerprint(before_links),'afterHrefHash':fingerprint(after_links) if a else None,'notes':notes})
summary={**before['summary'],'notApiWired':sum(not r['apiTemplate'] for r in rows),'ctaChangedArticles':sum(r['ctaCopyChanged'] for r in rows),'bodyChangedArticles':sum(r['bodyChanged'] for r in rows),'shortArticlesUnder650Words':sum(r['wordsBefore']<650 for r in rows),'sections':dict(collections.Counter(r['route'].split('/')[1] for r in rows))}
report={'checkedAt':before['checkedAt'],'scope':'All 325 canonical sitemap pages; 298 articles and deal guides. Hubs, tools, policies and the trial video are listed separately. Prior built-route cross-check found only a legacy redirect, icons and non-indexed alert tools outside the sitemap.','method':'Source import inspection establishes API wiring. Live HTML data-amazon-source markers establish displayed API/fallback data, not a fresh authenticated API response. Benefit and tradeoff excerpts are discovery aids, not independent factual certification or a paid editorial score. No claim of measured click uplift.','summary':summary,'articles':rows,'excludedPages':[{'route':r['route'],'title':r['title'],'status':r['status']} for r in before['rows'] if not r['article']]}
(out/'inventory.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
esc=html.escape
trs=[]
for r in rows:
 cls='good' if r['apiStatus']=='API data displayed' else 'warn' if r['apiTemplate'] else 'neutral'
 notes='<br>'.join(esc(n) for n in r['notes']) or 'Existing reader-fit guidance and retailer action retained.'
 trs.append(f'<tr data-status="{esc(r["apiStatus"])}"><td><a href="{esc(r["url"])}" target="_blank" rel="noopener">{esc(r["title"])}</a><small>{esc(r["route"])}</small></td><td><span class="pill {cls}">{esc(r["apiStatus"])}</span><small>{r["amazonLinks"]} Amazon links · {esc(", ".join(r["tags"]))}</small></td><td>{esc(r["readerBenefitEvidence"])}<details><summary>Tradeoff evidence and review notes</summary><p>{esc(r["tradeoffEvidence"]) or "No explicit skip/avoid phrase detected."}</p><p>{notes}</p><small>{esc(r["source"])}</small></details></td><td>{"Updated" if r["bodyChanged"] else "Retained" if after else "Awaiting build comparison"}<small>{r["wordsBefore"]} words before</small></td></tr>')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BestPickZone · Article and Amazon API inventory</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#172438;font:16px/1.5 system-ui,sans-serif}main{max-width:1450px;margin:auto;padding:36px 24px}h1{font-size:clamp(27px,4vw,44px);line-height:1.15;max-width:850px;margin:10px 0 20px}h2{font-size:21px}.eyebrow{color:#0f766e;font-size:13px;letter-spacing:.12em;font-weight:750}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:24px 0}.card{background:white;border:1px solid #d7e2ea;border-radius:16px;padding:20px}.number{display:block;font-size:34px;font-weight:800}.note{background:#e6f2ef;padding:20px;border-radius:14px;max-width:1100px}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:28px 0 14px}input,select{padding:12px;border:1px solid #9daebd;border-radius:9px;font:inherit}input{flex:1;min-width:220px}table{border-collapse:collapse;width:100%;background:white}th,td{text-align:left;vertical-align:top;padding:16px;border-bottom:1px solid #dce4eb}th{background:#172438;color:white;font-size:13px}td:first-child{width:27%}td:nth-child(3){width:42%;font-size:14px}a{color:#075e83;font-weight:650}small{display:block;color:#566574;font-size:12px;margin-top:9px;overflow-wrap:anywhere}.pill{display:inline-block;border-radius:8px;padding:5px 9px;font-size:12px;font-weight:700}.good{background:#d0f3df;color:#125c35}.warn{background:#fff0c6;color:#765400}.neutral{background:#edf0f4;color:#3c5065}details{margin-top:12px}summary{cursor:pointer;color:#075e83}p{max-width:1100px}.table{overflow:auto}footer{font-size:13px;color:#566574;padding:20px 0}@media(max-width:700px){main{padding:24px 14px}.cards{grid-template-columns:repeat(2,1fr)}table{min-width:920px}}</style><main><div class="eyebrow">BESTPICKZONE / OCTOBER 12, 2026</div><h1>What is connected to Amazon—and what gives readers a reason to click?</h1><p>Every published article and deal guide, with API evidence, reader-fit excerpts, and copy-review notes.</p><div class="cards"><div class="card"><span class="number">298</span>articles and guides</div><div class="card"><span class="number">3</span>API-connected articles</div><div class="card"><span class="number">1</span>article displaying API data</div><div class="card"><span class="number">2</span>connected articles in fallback</div></div><div class="note"><strong>The API is not site-wide.</strong> Breville Bambino Plus vs Gaggia Classic Pro displays two Amazon-supplied product cards and direct product URLs. Alex Michaelides and Stream Deck/MX Creative Console display search-link fallbacks. The other 295 articles have no Creators API integration; this includes eBay and membership guides where product-card integration may not be appropriate.</div><h2>Reader-first copy changes</h2><p><strong>141 articles have clearer calls to action; 146 have some copy change.</strong> Changes are prepared in <a href="https://github.com/simputech/bestpickzone/pull/9">draft PR #9</a>. The hosted build and all 325 page checks passed. Browser visual QA remains incomplete because local automation processes were killed; production is unchanged. <a href="validation.json">Validation details</a>.</p><p>Generic purchase buttons now explain the next step: compare book editions and prices, or check the exact product model and price. Selected weak passages now explain dimensions, compatibility, included parts, and total cost. The urban-fantasy guide corrects ongoing-series claims. Existing API-card work in PR #6 remains separate.</p><p><strong>This is an integration and buying-copy audit, not a claim that every article has received a new factual review.</strong> Short articles and missing explicit tradeoffs remain visible in the notes. Click improvement has not been measured.</p><div class="controls"><input id="search" type="search" aria-label="Search articles" placeholder="Search title, category, or buying reason"><select id="filter" aria-label="Filter API status"><option value="">All API statuses</option><option>API data displayed</option><option>API wired; fallback displayed</option><option>No Creators API integration</option></select></div><p id="count" aria-live="polite"></p><div class="table"><table><thead><tr><th>Article</th><th>Amazon API status</th><th>Existing reader benefit / review evidence</th><th>Copy pass</th></tr></thead><tbody>ROWS</tbody></table></div><footer>Live snapshot: TIME. Scope: 325 sitemap URLs, all returned HTTP 200. Inventory excludes 27 hubs, tools, policy and media pages. API markers can represent cached data. No credentials or live test analytics were collected.</footer></main><script>const rows=[...document.querySelectorAll('tbody tr')];function filter(){const q=document.querySelector('#search').value.toLowerCase(),status=document.querySelector('#filter').value;let n=0;for(const row of rows){const show=row.textContent.toLowerCase().includes(q)&&(!status||row.dataset.status===status);row.hidden=!show;if(show)n++}document.querySelector('#count').textContent=n+' of '+rows.length+' articles shown'}document.querySelector('#search').addEventListener('input',filter);document.querySelector('#filter').addEventListener('change',filter);filter()</script></html>'''.replace('ROWS',''.join(trs)).replace('TIME',esc(before['checkedAt']))
(out/'index.html').write_text(page)
print(json.dumps(summary,indent=2))
